WITH w AS (SELECT winner_id, winner_name, COUNT(*) AS wins FROM matches GROUP BY winner_id),
top AS (SELECT * FROM w WHERE wins = (SELECT MAX(wins) FROM w))
SELECT t.winner_name, (SELECT m.winner_rank_points FROM matches m WHERE m.winner_id = t.winner_id ORDER BY m.tourney_date DESC, m.match_num DESC LIMIT 1) AS rank_points FROM top t;
